    [2032]={name="Gallan Cuffs",quality=2,ilvl=36,reqLevel=27,sourceType="quest_reward",instructions="Reward from the quest 'To Steal From Thieves'. Pick it over the other reward choices. Starts with Genavie Callow in Undercity. Objective: Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.",zone="Undercity",questName="To Steal From Thieves",lore="The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."},
    [2033]={name="Ambassador's Boots",quality=3,ilvl=28,reqLevel=22,sourceType="quest_reward",instructions="Reward from the quest 'Crime and Punishment'. Pick it over the other reward choices. Starts with Councilman Millstipe in Duskwood. Objective: Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.",zone="The Stockade",questName="Crime and Punishment"},
