    [2816]={name="Death Speaker Scepter",quality=3,ilvl=33,reqLevel=28,sourceType="boss_drop",instructions="Drops from Death Speaker Jargba.",zone="Razorfen Kraul",npc="Death Speaker Jargba"},
    [2817]={name="Soft Leather Tunic",quality=2,ilvl=12,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'Protecting the Herd'. Pick it over the other reward choices. Starts with Rudra Amberstill in Dun Morogh. Objective: Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.",zone="Dun Morogh",questName="Protecting the Herd",lore="We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."},
    [2818]={name="Stretched Leather Trousers",quality=2,ilvl=15,reqLevel=12,sourceType="quest_reward",instructions="Reward from the quest 'Pyrewood Ambush'. Pick it over the other reward choices. Starts with Deathstalker Faerleia in Silverpine Forest. Objective: Help Deathstalker Faerleia kill the Pyrewood Council.",zone="Silverpine Forest",questName="Pyrewood Ambush",lore="You got here just in the nick of time! The Pyrewood Council will be returning any moment. Arugal has other matters to tend to in the keep. He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control."},
    [2823]={name="Mo'grosh Can Opener",quality=2,ilvl=19,reqLevel=14,sourceType="world_drop",instructions="Drops from Mo'grosh Brute.",zone="Loch Modan",npc="Mo'grosh Brute",zoneOpen=true},
