    [22961]={name="Band of Reanimation",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Patchwerk.",zone="Naxxramas",npc="Patchwerk",lore="An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."},
